void tr_trigger_oem( void )
{
    if( tr_lock_status )
    {
        ATOMIC(tr_status=TRUE);
        
        ATOMIC(tr_oem=TRUE); 

        timeout_q_remove((Timeout_Q_Func)tr_timeout) ; 
        timeout_q_insert((Timeout_Q_Func)tr_timeout,NULL,TR_TIMEOUT,1,1) ;
		

		TRACE("\n\r[TR_TRIGGER_OEM]\n\r");
    }
}         

//--------------------------------------------------------------------------//

void tr_trigger_rs( void )
{
   if( tr_lock_status )
    {
        ATOMIC(tr_status=TRUE);
        ATOMIC(tr_oem  =FALSE); 

        timeout_q_remove((Timeout_Q_Func)tr_timeout) ; 
        timeout_q_insert((Timeout_Q_Func)tr_timeout,NULL,TR_TIMEOUT,1,1) ;
		
				

        TRACE("\n\r[TR_TRIGGER_RS]\n\r");
    }
}         

